callGraph.callee:
fetch("/api/record")
      .then((r) => r.json())
      .then((d) => {
        if (d?.ok && Array.isArray(d.calls) && d.calls.length) {
          const qs = d.calls
            .map((c: { question?: string }) => c.question)
            .filter(Boolean)
            .slice(0, 3);
          if (qs.length) setChips(qs);
        }
      })
      .catch

fetch("/api/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            conversation_id: convIdRef.current,
            content: prose,
            reasoning: reasoningAcc || null,
          }),
        }).catch

fetch("/api/checkout")
      .then((r) => r.json())
      .then((d) => {
        setBillingOn(Boolean(d?.configured));
        if (Array.isArray(d?.packs)) setPacks(d.packs);
        if (Array.isArray(d?.plans)) setPlans(d.plans);
      })
      .catch
